// ============================================================================
// fieldShort.expanded.cpp -- WinSky active field shortlist
// ============================================================================
// AUTO-EXPANDED REFERENCE FILE -- generated by macro-expanding every Test()
// (WinSky "field" DSL) block in pixel/fieldShort.sky.h into a plain C++ function.
// This file is NOT compiled as part of any build; it exists purely as a
// human-readable porting reference.  Math and variable names are preserved
// verbatim from the source macros.
//
// Field function count expanded: 24
//
// ---- Field DSL model (pixel/Field.cpp) ----
// A "field" is a per-screen-pixel coordinate WARP (a feedback distortion
// map), NOT a per-frame time-driven animation like wave shapes.  For every
// destination pixel (x,y) on a xs*ys grid (x in [-aspect,aspect], y in
// [-1,1]; radius,theta = that pixel's polar coordinates, precomputed once by
// Field::calcRT()), the field body computes a SOURCE coordinate (in
// Cartesian or polar form) to sample from the PREVIOUS rendered frame.  The
// engine blends the sampled previous-frame pixel with the new incoming pixel
// (Field::go(), fade[] decay table) every frame, so what LOOKS like
// animation (zoom/spin/ripple) is really the accumulated effect of applying
// the SAME static warp over and over across successive frames, not an
// explicit `t` (time) term -- most fields have no time input at all.  A few
// use rnd() to add fresh per-pixel jitter every frame.
//
// ---- runtime inputs available inside macro bodies ----
// x, y         current destination pixel, normalized to roughly
//              x in [-aspect,aspect], y in [-1,1] (pixel/Field.cpp ForXY)
// radius,theta current destination pixel's polar coordinates, precomputed
//              once per grid by Field::calcRT() (radius=sqrt(x^2+y^2),
//              theta=atan2(y,x) wrapped to [0,2*PI))
// a[16]        setup constants, evaluated ONCE when this field is selected
//              (literal `a[i] = expr;` statements ahead of the Go*() call;
//              NOT reset between frames, unlike wave a[]/b[]/c[])
// d[16]        optional "delta"/feedback channels, used by the GoD*RT/
//              GoD*XY macro family; computed fresh each pixel each frame,
//              available to the coordinate expressions that follow them in
//              the same Go*() call
// rnd(n), dabs, trnc, flor, wrap, clip, pos, sgn, trwv, saw, sqwv, seed, sqr
//              pixel/FieldFunc.cpp (shared with waves)
// PI           3.14159265358979 (pixel/Field.cpp local #define)
//
// NOTE: unlike wave shapes, field bodies have NO access to `t` (elapsed
// time), `mag()`/`fft()` (audio), or `id`/`num` (instance index) -- fields
// are audio-*blind* by construction; only wave shapes read audio directly.
// (Camera/draw input can still reach the field stage upstream via the
// pixe.cell/pipe.draw compositing chain, but not inside the Test() math.)
//
// ---- selection / dispatch (pixel/Field.cpp Field::calcMap) ----
// Test(name,author,email,desc) macro-expands to a sequential
// `if (test++ == oldAlgo) { ...; calcViz(); return; }` chain (see
// CallTree.waves.md); the Nth Test() in the file is field-selector index
// N+1 (index 0 == "None", the passthrough hard-coded ahead of the chain).
//
// ---- Go*() coordinate-warp macro family (pixel/Field.cpp) ----
// GoXY(X,Y,Aspect)              Cartesian warp, 0 feedback channels
// GoDXY(D0,X,Y,Aspect)          Cartesian warp, 1 feedback channel
// GoD2XY(D0,D1,X,Y,Aspect)      Cartesian warp, 2 feedback channels
// GoD3XY(D0,D1,D2,X,Y,Aspect)   Cartesian warp, 3 feedback channels
// GoD4XY(D0..D3,X,Y,Aspect)     Cartesian warp, 4 feedback channels
// GoD8XY(D0..D7,X,Y,Aspect)     Cartesian warp, 8 feedback channels
// GoRT(R,T,Aspect)              polar warp, 0 feedback channels
// GoDRT(D0,R,T,Aspect)          polar warp, 1 feedback channel
// GoD2RT(D0,D1,R,T,Aspect)      polar warp, 2 feedback channels
// GoD3RT(D0,D1,D2,R,T,Aspect)   polar warp, 3 feedback channels
// Cartesian result feeds Field::setXY(X,Y) [Field.cpp:179]; polar result
// feeds Field::setRT(R,T) [Field.cpp:187].  Both converge on the same
// from-X/Y/R/T state used to sample the previous-frame buffer and to
// auto-range min/max R/T/deltaR/deltaT for the "viz" false-color modes.
// ============================================================================

#include <cmath>
#include <algorithm>

using std::sin; using std::cos; using std::tan; using std::atan; using std::atan2;
using std::sqrt; using std::pow; using std::fmod; using std::log; using std::exp;
using std::min; using std::max; using std::abs;

// ---- helpers from pixel/FieldFunc.cpp (prototypes; shared by waves+fields) ----
double dabs(double num);
double sqr(double num);
double rnd(double range);
double trnc(double num);
double flor(double num);
double wrap(double x);
double clip(double num);
double pos(double num);
double sgn(double x);
double trwv(double x);
double saw(double x);
double sqwv(double x);
double seed(double x);

#ifndef PI
#define PI  (3.14159265358979f)   // pixel/Field.cpp local redefinition (float, not double!)
#endif

// Result of one field warp evaluation for a single destination pixel.
// polar==false -> (v0,v1) is (sourceX,sourceY), feed to Field::setXY().
// polar==true  -> (v0,v1) is (sourceR,sourceTheta), feed to Field::setRT().
struct FieldResult { double aspect; bool polar; double v0, v1; };


