// Field: Ether Leak
// Macro:  Test("Ether Leak", "Jay Protopapas", "philodoh(at)aol.com", "")
// Source: pixel/fieldShort.sky.h:1
// Author: Jay Protopapas  <philodoh(at)aol.com>
// Warp kind: GoRT  (polar, 0 feedback channel(s))  Aspect=0.25
// ==============================================================================
FieldResult field_Ether_Leak(float a[16], float d[16], double x, double y, double radius, double theta)
{
    // ---- setup: literal constants, evaluated ONCE when this field is selected ----
    // (no a[] setup constants)

    // ---- per pixel: GoRT(...) -- evaluated for every (x,y) on the grid ----
    double sourceR = (radius * clip(1.57 + 1.256 * sin(sgn(0.057 - sin(radius)))));
    double sourceT = (theta - sqrt(flor(rnd(1.00999))));
    return FieldResult{ 0.25, true, sourceR, sourceT };  // -> Field::setRT(sourceR, sourceT)
}

